let current='en';try{const saved=localStorage.getItem('tube-u-cat-language');if(locales[saved])current=saved;}catch{}
const set=(selector,text)=>{const el=document.querySelector(selector);if(el)el.textContent=text;};
const attr=(selector,name,text)=>document.querySelector(selector)?.setAttribute(name,text);
function apply(language){
 current=locales[language]?language:'en';const d=locales[current];document.documentElement.lang=d.lang;document.title=d.title;attr('meta[name="description"]','content',d.meta);
 set('.tag',d.tag);document.querySelector('h1').innerHTML=d.hero;document.querySelector('.hero .intro').innerHTML=d.intro;
 attr('section[aria-label]','aria-label',d.player);attr('#drawing','aria-label',d.drawing);set('#reset',d.reset);set('label[for="seek"]',d.seek);attr('.beats','aria-label',d.beatsLabel);
 document.querySelectorAll('.beats button').forEach((b,i)=>b.textContent=d.beats[i]);
 set('.story > div:first-child h2',d.startTitle);set('.story > div:first-child > p:not(.eyebrow):not(.note)',d.startBody);set('.actions a:first-child',d.download);set('.actions a:nth-child(2)',d.skill);set('.note',d.note);set('.story > div:nth-child(2) h2',d.promptTitle);set('#prompt',d.prompt);set('#copy',d.copy);set('#copied','');
 const details=document.querySelectorAll('details');details[0].querySelector('summary').textContent=d.how;details[0].querySelectorAll('li').forEach((li,i)=>li.textContent=d.steps[i]);details[0].querySelector('p').textContent=d.uploadNote;details[1].querySelector('summary').textContent=d.about;details[1].querySelector('p').textContent=d.aboutBody;
 const footer=document.querySelector('footer');footer.firstChild.textContent=d.footer;footer.querySelector('a').textContent=d.footerLink;
 attr('.languages','aria-label',d.language);document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===current)));
 try{localStorage.setItem('tube-u-cat-language',current);}catch{}
 window.dispatchEvent(new CustomEvent('cat-language-change'));
}
window.catI18n={t:key=>locales[current][key],set:apply,locales};document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>apply(b.dataset.lang)));apply(current);
